from taf.cloud.cbam.catalog.catalog import Catalog
from taf.cloud.cbam.exception import VnfdidPkgNotFound


class Catalog19(Catalog):
    def __init__(self, session):
        self._session = session

    def _send_to_endpoint(self, method, endpoint, api_version=None, **content):
        response = self._session.send_request(
            method=method,
            endpoint=endpoint,
            api_version=api_version,
            **content)
        return response

    def get_info(self, api_version=None):
        response = self._send_to_endpoint(method='get',
                                          endpoint='vnfpkgm/v1/vnf_packages',
                                          api_version=api_version)
        return response.data

    def _create_vnf_package_object(self, api_version):
        endpoint = 'vnfpkgm/v1/vnf_packages'
        response = self._send_to_endpoint(method='post',
                                          endpoint=endpoint,
                                          api_version=api_version)
        return response.data["id"]

    def _onboard_vnf_package(self, vnf_pkg_id, cbam_catalog_zip, api_version=None):
        put_endpoint = 'vnfpkgm/v1/vnf_packages/{vnf_pkg_id}/package_content'.format(vnf_pkg_id=vnf_pkg_id)
        put_response = self._send_to_endpoint(method='put',
                                              endpoint=put_endpoint,
                                              content_type='application/zip',
                                              data=cbam_catalog_zip,
                                              api_version=api_version)
        data = put_response.data
        return data

    def post_info(self, cbam_catalog_zip, api_version=None):
        vnf_pkg_id = self._create_vnf_package_object(api_version=api_version)
        return self._onboard_vnf_package(vnf_pkg_id=vnf_pkg_id,
                                         cbam_catalog_zip=cbam_catalog_zip,
                                         api_version=api_version)

    def _get_vnf_package_id(self, vnfd_id, api_version=None):
        vnf_pkg_list = self.get_info(api_version=api_version)
        for vnf_package in vnf_pkg_list:
            if vnf_package.get('vnfdId') == vnfd_id:
                vnf_pkg_id = int(vnf_package.get('id'))
                break
        else:
            raise VnfdidPkgNotFound("Catalog with vnfd_id = {} not found in CBAM".format(vnfd_id))
        return vnf_pkg_id

    def delete_info(self, vnfd_id, api_version=None):
        vnf_pkg_id = self._get_vnf_package_id(vnfd_id=vnfd_id, api_version=api_version)
        endpoint = 'vnfpkgm/v1/vnf_packages/{}'.format(vnf_pkg_id)
        response = self._send_to_endpoint(method='delete',
                                          endpoint=endpoint,
                                          api_version=api_version)
        data = response.data
        return data
